type JsonObject = Record<string, unknown>;

type PackageWord = {
  id: string;
  position: number;
  arabic: string;
  gloss?: string;
  teachingId?: string;
  [key: string]: unknown;
};

type PackageAyah = {
  id: string;
  number: number;
  arabic?: string;
  words: PackageWord[];
  [key: string]: unknown;
};

type LessonForm = {
  form: string;
  meaning: string;
  difference: string;
  relationship?: string;
  provenance?: string;
};

type SarfReview = {
  status: "full" | "limited";
  limitedReason?: string;
  auditDecision?:
    | "confirmed-limited"
    | "upgraded-to-full"
    | "blocked-for-genuine-ambiguity";
  provenance: string[];
  reviewedBy: string;
  reviewedAt: string;
};

type TeachingLesson = {
  id: string;
  meaning: string;
  type: string;
  root: string;
  rootPicture: string;
  forms: LessonForm[];
  sarfReview: SarfReview;
  [key: string]: unknown;
};

type SourcePackage = {
  packageId: string;
  contentVersion: string;
  status: "source-only" | "custom-partial" | "custom-complete";
  surah: { number: number; name?: string };
  ayahs: PackageAyah[];
  teachingEntries: Record<string, TeachingLesson>;
  [key: string]: unknown;
};

type Feature = { key?: string; label?: string; value?: string };

type ProviderEvidence = {
  occurrenceId: string;
  recordKey: string;
  version: string;
  root: string;
  lemma: string;
  pattern: string;
  partOfSpeech: string;
  lexicalStem?: string;
  features: Feature[];
};

type ProviderRow = {
  occurrence_id: string;
  record_key: string | null;
  version: string | null;
  part_of_speech: string | null;
  features: unknown;
};

type Occurrence = {
  packagePath: string;
  pkg: SourcePackage;
  ayah: PackageAyah;
  word: PackageWord;
  lesson: TeachingLesson;
  provider?: ProviderEvidence;
};

type Candidate = LessonForm & {
  score: number;
  sourceOccurrence?: string;
  sourceKind:
    | "canonical-occurrence"
    | "existing-reviewed-row"
    | "codex-authored-lexicon";
  featureSignal: string[];
  baseDistinct: boolean;
  lexicalKey: string;
};

type Decision = "confirmed-limited" | "upgraded-to-full" | "blocked-for-genuine-ambiguity";

